{"command":["bash","-lc","cat > /tmp/an.py <<'PY'
import json,collections,statistics,math
recs=[]
for line in open('/app/lab_log.jsonl'):
 x=json.loads(line)
 if x.get('op')=='dev_sample': recs += x['result']['questions']
print('n',len(recs))
def pick(ss,mode):
 by=collections.defaultdict(list)
 for s in ss:by[s['answer']].append(s)
 def key(a):
  z=by[a]; scores=[x['score'] for x in z]
  if mode=='maj':return (len(z),sum(scores))
  if mode=='sum':return sum(scores)
  if mode=='mean':return sum(scores)/len(z)
  if mode[0]=='t':return sum(x>float(mode[1:]) for x in scores)
  if mode[0]=='e':return sum(math.exp(float(mode[1:])*x) for x in scores)
  if mode[0]=='l':return len(z)+float(mode[1:])*sum(scores)
 vals={a:key(a) for a in by};mx=max(vals.values())
 return next(x['answer'] for x in ss if vals[x['answer']]==mx)
for t in ['algebra','geometry','combinatorics','number_theory']:
 qs=[q for q in recs if q['topic']==t]
 print('\n',t,len(qs))
 for v in range(5):
  ss=[s for q in qs for s in q['samples'] if s['variant']==v]
  good=[s['score'] for s in ss if s['correct']];bad=[s['score'] for s in ss if not s['correct']]
  print(v,'acc',round(sum(x['correct'] for x in ss)/len(ss),3),'score',round(statistics.mean(good),2),round(statistics.mean(bad),2),'pos',round(sum(x>0 for x in good)/len(good),2),round(sum(x>0 for x in bad)/len(bad),2))
 for k in [1,2,3,4,5,6,8]:
  print(' k',k,end=' ')
  for mode in ['maj','sum','mean','t0','t.3','t.5','t.8','t1','e1','e2']:
   z=0
   for q in qs:
    ss=[s for s in q['samples'] if s['variant'] in range(5)]
    # first k from each variant? all variants k => 5k
    ss=[s for v in range(5) for s in q['samples'] if s['variant']==v][:0]
    ss=[]
    for v in range(5):ss += [s for s in q['samples'] if s['variant']==v][:k]
    z+=pick(ss,mode)==q['correct_answer']
   print(mode,round(z/len(qs),2),end=';')
  print()
