exec(open('/tmp/an.py').read().split("for t in")[0])
def p2(ss,mode):
 by=collections.defaultdict(list)
 for s in ss:by[s['answer']].append(s)
 vals={}
 for a,z in by.items():
  per=collections.defaultdict(list)
  for s in z:per[s['variant']].append(s)
  if mode=='vcount': vals[a]=len(per)
  elif mode=='vmaj': vals[a]=sum(1 for v in per if collections.Counter(s['answer'] for s in ss if s['variant']==v).most_common(1)[0][0]==a)
  elif mode=='cap': vals[a]=sum(min(1,len(per[v])) for v in per)
  elif mode.startswith('capth'):
   th=float(mode[6:]); vals[a]=sum(1 for v,zv in per.items() if any(s['score']>th for s in zv))
  elif mode.startswith('sumth'):
   th=float(mode[5:]); vals[a]=sum(max(0,s['score']-th) for s in z)
  elif mode.startswith('nscore'):
   th=float(mode[6:]); vals[a]=sum(1 for s in z if s['score']>th)+0.2*sum(s['score'] for s in z)
  elif mode=='minmean': vals[a]=len(z)*(-abs(sum(s['score'] for s in z)/len(z)-.9))
  elif mode.startswith('countth'):
   th=float(mode[7:]);vals[a]=sum(s['score']>th for s in z)
 mx=max(vals.values());return next(s['answer'] for s in ss if vals[s['answer']]==mx)
for t in ['algebra','geometry','combinatorics','number_theory']:
 qs=[q for q in recs if q['topic']==t]
 print(t)
 for k in [1,2,3,4,6,8]:
  ss=[]
  for q in qs:
   z=[]
   for v in range(5):z += [s for s in q['samples'] if s['variant']==v][:k]
   ss.append((q,z))
  print('k',k,end=' ')
  for m in ['vcount','vmaj','cap','capth0','capth.3','capth.5','countth0','countth.3','countth.5','sumth0','sumth.3','sumth.5','nscore0','nscore.3']:
   z=sum(p2(s,m)==q['correct_answer'] for q,s in ss)/len(qs)
   print(m,round(z,2),end=';')
  print()
